def is_not_prime(n):  # Define your function here!  
    if n <= 1 or (n % 2 == 0 and n > 2): 
        return True     # Prime numbers are greater than one, so we can start checking from there. If the number has a factor other than itself & 1 then it is not prime otherwise true; also check for even factors after that to avoid unnecessary iterations (since all primes except two have already been checked).  
    else:     # Checking if n divisible by any numbers upto square root of 'n' because larger values will be multiples.  If the number is not prime then it can only divide into one factor, so we return False; otherwise True (i.e., Prime Number)      
        for i in range(3, int(n**0.5) + 1 ,2):   # Start from 'three' and go up to square root of n because a larger value will be multiples 
            if not ((n % i == 0)):    # If the number is divisible by any other numbers then it isn’t prime, so return False. Otherwise True (i.e., Prime Number)      
                break  
        else :     # This means that no factors were found and thus 'True' was returned in previous if block – hence we need to make sure this is the case too:   
            return False

def sum_div(n):   # define our function here that takes a number n as input and returns its divisor's sums (i.e., the total count)
    return sum([x for x in range(1, int(math.sqrt(abs(n))) + 1 if abs(n % x == 0)] + [int(n / 2),]) # list comprehension to get all divisors and then add n/2 (if it's a perfect square)

