    n = len(arr)    

    # Traverse through the array from bottom up. If a parent is larger than its children, return False; otherwise continue traversing till root level and then if any leaf nodes are present after that also returning false 

    for i in range((n//2)-1,-1,-1):  
        # Check if left child exists (i*2+1) is less than size of array. If yes, check right subtree as well    

